observation.command:
cd /workspace/example && (nohup npx vite preview --port 4173 > /tmp/preview.log 2>&1 &) ; sleep 6; curl -s -o /tmp/pv.html -w "preview root: %{http_code}
" http://localhost:4173/; grep -o "<title>.*</title>" /tmp/pv.html; js=$(grep -oE '/assets/index-[^"]+\.js' /tmp/pv.html | head -1); css=$(grep -oE '/assets/index-[^"]+\.css' /tmp/pv.html | head -1); curl -s -o /dev/null -w "built js: %{http_code} size=%{size_download}
" "http://localhost:4173$js"; curl -s -o /dev/null -w "built css: %{http_code} size=%{size_download}
" "http://localhost:4173$css"; echo "--- preview log ---"; cat /tmp/preview.log
